import{_ as e,o as n,c as s,ai as t}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Python · 04 工程实践","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/python/04-engineering.md","filePath":"tech-system/backend/python/04-engineering.md"}'),i={name:"tech-system/backend/python/04-engineering.md"};function l(r,a,p,d,o,h){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="python-·-04-工程实践" tabindex="-1">Python · 04 工程实践 <a class="header-anchor" href="#python-·-04-工程实践" aria-label="Permalink to “Python · 04 工程实践”">​</a></h1><blockquote><p>和 Java 怎么协作、项目怎么落、怎么测怎么部署。</p></blockquote><h2 id="_1-与-java-的分工-强制想清楚" tabindex="-1">1. 与 Java 的分工（强制想清楚） <a class="header-anchor" href="#_1-与-java-的分工-强制想清楚" aria-label="Permalink to “1. 与 Java 的分工（强制想清楚）”">​</a></h2><table tabindex="0"><thead><tr><th>放在 Java</th><th>放在 Python</th></tr></thead><tbody><tr><td>用户、权限、配额、计费状态</td><td>调模型、拼 Prompt、后处理</td></tr><tr><td>任务表、状态机、可重试权威记录</td><td>无状态或短生命周期 worker</td></tr><tr><td>对前端的主 API</td><td>内部模型代理 / 批处理 Job</td></tr></tbody></table><p>反例：只在 Python 里 <code>sqlite</code> 记任务，Java 不知情 → 对账与客服查单灾难。</p><p>正例（AI 漫剧类）：</p><ol><li>Java 创建任务（pending）</li><li>Python / 或 Java 调模型（执行中）</li><li>结果回写 Java（成功/失败/可重试原因）</li><li>前端只信 Java 的状态</li></ol><hr><h2 id="_2-推荐的最小项目结构" tabindex="-1">2. 推荐的最小项目结构 <a class="header-anchor" href="#_2-推荐的最小项目结构" aria-label="Permalink to “2. 推荐的最小项目结构”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>app/</span></span>
<span class="line"><span>  main.py           # FastAPI 入口</span></span>
<span class="line"><span>  api/              # 路由</span></span>
<span class="line"><span>  schemas/          # Pydantic</span></span>
<span class="line"><span>  services/         # 调模型、业务胶水</span></span>
<span class="line"><span>  core/config.py    # 环境变量</span></span>
<span class="line"><span>tests/</span></span>
<span class="line"><span>pyproject.toml / requirements.txt</span></span>
<span class="line"><span>Dockerfile</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>原则：</p><ul><li>路由瘦、service 胖一点但别做成上帝类</li><li>密钥走环境变量；示例用 <code>.env.example</code></li><li>模型名、温度、超时做成配置，方便不改代码试参</li></ul><hr><h2 id="_3-异步任务怎么做-实用档" tabindex="-1">3. 异步任务怎么做（实用档） <a class="header-anchor" href="#_3-异步任务怎么做-实用档" aria-label="Permalink to “3. 异步任务怎么做（实用档）”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>做法</th></tr></thead><tbody><tr><td>最早</td><td>接口同步调模型（只适合 Demo）</td></tr><tr><td>中小</td><td>任务表（可在 Java）+ 后台协程/进程消费</td></tr><tr><td>更大</td><td>Redis/MQ + 多 worker；死信与告警</td></tr></tbody></table><p>必须具备：<strong>幂等、超时、重试上限、错误分类、可人工重跑</strong>。</p><hr><h2 id="_4-测试" tabindex="-1">4. 测试 <a class="header-anchor" href="#_4-测试" aria-label="Permalink to “4. 测试”">​</a></h2><ul><li>纯函数 / Prompt 组装：pytest</li><li>HTTP：<code>TestClient</code>；外部模型 mock</li><li>「黄金样例」：固定输入看输出结构是否仍符合 schema（模型内容可变，结构要稳）</li></ul><hr><h2 id="_5-依赖与部署" tabindex="-1">5. 依赖与部署 <a class="header-anchor" href="#_5-依赖与部署" aria-label="Permalink to “5. 依赖与部署”">​</a></h2><ul><li>锁文件进仓库；CI 用同一锁安装</li><li>Docker：瘦基础镜像；别把宿主机 venv 拷进镜像思路搞反</li><li>配置：<code>ENV</code> 区分；生产关 debug、关自动重载</li><li>观察：请求日志带 <code>task_id</code>；模型耗时、token/费用单独打点</li></ul><h3 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to “本地开发”">​</a></h3><ul><li><code>uvicorn app.main:app --reload</code></li><li>与 Java 联调：先约定 OpenAPI，再用示例 curl/httpie 固化</li></ul><p>下一篇：<a href="./05-faq.html">05 常见问题</a><br> 速成路线：<a href="/my-vitepress-site/tech-system/python/python-skill.html">Python 技能速成</a></p>`,25)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
